{
  "name": "IEEE 488/GPIB 实验仪器",
  "name_en": "IEEE 488/GPIB laboratory instrument",
  "manufacturer": "",
  "description": "通过 IEEE 488（GPIB）总线连接和控制的台式实验仪器，如万用表、示波器、信号源或电源。此类设备常用于实验室自动化测试、状态查询、触发同步以及保存或恢复仪器配置。",
  "description_en": "A bench-top laboratory instrument connected and controlled through the IEEE 488 (GPIB) bus, such as a multimeter, oscilloscope, signal generator, or power supply. Devices in this class are commonly used for automated testing, status monitoring, trigger synchronization, and saving or recalling instrument configurations.",
  "tag_hints": [
    "GPIB",
    "IEEE 488",
    "SCPI common commands",
    "test and measurement",
    "instrument automation",
    "status registers",
    "trigger synchronization"
  ],
  "actions": [
    {
      "action_name": "auto-ESE",
      "description": "设置事件状态使能寄存器",
      "description_en": "set the event status enable register"
    },
    {
      "action_name": "auto-OPC",
      "description": "获取/设置操作完成位",
      "description_en": "get/set the operation complete bit"
    },
    {
      "action_name": "auto-RCL",
      "description": "调用已保存的仪器状态",
      "description_en": "recall a saved instrument state"
    },
    {
      "action_name": "auto-RST",
      "description": "将仪器复位到默认状态",
      "description_en": "reset the instrument to its default state"
    },
    {
      "action_name": "auto-SAV",
      "description": "保存当前仪器状态",
      "description_en": "save the current instrument state"
    },
    {
      "action_name": "auto-SRE",
      "description": "设置服务请求使能寄存器",
      "description_en": "set the service request enable register"
    },
    {
      "action_name": "auto-GTL",
      "description": "切换到本地面板控制",
      "description_en": "return the instrument to local front-panel control"
    }
  ]
}

